1	import Link from "next/link";
2	import { Reveal } from "./Reveal";
3	
4	/**
5	 * Marketing layout primitives (v2 redesign) — the single reuse layer every page
6	 * is built from, so the whole site reads as one designed thing.
7	 *
8	 *  - <Section>   full-width band with an alternating background "tone" and a
9	 *                consistent vertical rhythm + content rail. Replaces the ad-hoc
10	 *                `mx-auto max-w-6xl px-5 py-20` strings copy-pasted everywhere.
11	 *  - <PageHero>  the standard sub-page hero (eyebrow → title → sub → CTAs +
12	 *                optional visual). Replaces ~10 hand-rolled hero blocks.
13	 *  - <Eyebrow>   the uppercase tag above a heading.
14	 *  - <SectionTitle> heading + optional sub, centered or left.
15	 *
16	 * Colors and animations are the existing brand system (navy + violet/blue).
17	 */
18	
19	type Tone = "base" | "panel" | "deep" | "light";
20	type Size = "sm" | "md" | "lg";
21	
22	const TONE: Record<Tone, string> = {
23	  base: "",
24	  panel: "tone-panel",
25	  deep: "tone-deep",
26	  light: "tone-light",
27	};
28	const PAD: Record<Size, string> = {
29	  sm: "py-14 sm:py-16",
30	  md: "py-20 sm:py-24",
31	  lg: "py-24 sm:py-32",
32	};
33	
34	/** A full-width section band. `tone` alternates the background for rhythm. */
35	export function Section({
36	  children,
37	  tone = "base",
38	  size = "md",
39	  id,
40	  className = "",
41	}: {
42	  children: React.ReactNode;
43	  tone?: Tone;
44	  size?: Size;
45	  id?: string;
46	  className?: string;
47	}) {
48	  return (
49	    <section id={id} className={`relative ${TONE[tone]} ${PAD[size]} ${className}`}>
50	      <div className="rail">{children}</div>
51	    </section>
52	  );
53	}
54	
55	/** Uppercase eyebrow tag. `pill` gives it the bordered chip treatment. */
56	export function Eyebrow({ children, pill = false }: { children: React.ReactNode; pill?: boolean }) {
57	  return <span className={pill ? "eyebrow-pill" : "eyebrow"}>{children}</span>;
58	}
59	
60	/** Section heading block: eyebrow + title + optional sub. */
61	export function SectionTitle({
62	  eyebrow,
63	  title,
64	  sub,
65	  align = "center",
66	  className = "",
67	}: {
68	  eyebrow?: string;
69	  title: React.ReactNode;
70	  sub?: React.ReactNode;
71	  align?: "center" | "left";
72	  className?: string;
73	}) {
74	  const alignCls = align === "center" ? "mx-auto text-center" : "text-left";
75	  return (
76	    <div className={`max-w-2xl ${alignCls} ${className}`}>
77	      {eyebrow && <Eyebrow>{eyebrow}</Eyebrow>}
78	      <h2 className="mt-3 text-3xl font-bold tracking-tight text-[var(--fg)] sm:text-4xl text-balance">{title}</h2>
79	      {sub && <p className="mt-4 text-lg leading-relaxed text-[var(--fg-muted)]">{sub}</p>}
80	    </div>
81	  );
82	}
83	
84	type Cta = { label: string; href: string };
85	
86	/**
87	 * Standard sub-page hero. Left-aligned title/sub/CTAs with an optional visual on
88	 * the right; falls back to centered when no visual is supplied. Renders the
89	 * reusable `.hero-aura` glow behind everything.
90	 */
91	export function PageHero({
92	  eyebrow,
93	  title,
94	  highlight,
95	  sub,
96	  primary,
97	  secondary,
98	  visual,
99	  children,
100	}: {
101	  eyebrow?: string;
102	  title: React.ReactNode;
103	  /** Optional trailing fragment rendered in the brand gradient. */
104	  highlight?: string;
105	  sub?: React.ReactNode;
106	  primary?: Cta;
107	  secondary?: Cta;
108	  visual?: React.ReactNode;
109	  children?: React.ReactNode;
110	}) {
111	  const centered = !visual;
112	  return (
113	    <section className="relative overflow-hidden">
114	      <div className="pointer-events-none absolute inset-0 -z-10 hero-aura" aria-hidden />
115	      <div className="rail py-20 sm:py-28">
116	        <div className={centered ? "mx-auto max-w-3xl text-center" : "grid items-center gap-12 lg:grid-cols-2"}>
117	          <Reveal>
118	            {eyebrow && <Eyebrow pill>{eyebrow}</Eyebrow>}
119	            <h1 className="mt-5 text-4xl font-bold leading-[1.08] tracking-tight text-white sm:text-5xl lg:text-6xl text-balance">
120	              {title}
121	              {highlight && (
122	                <>
123	                  {" "}
124	                  <span className="grad-text">{highlight}</span>
125	                </>
126	              )}
127	            </h1>
128	            {sub && (
129	              <p className={`mt-6 text-lg leading-relaxed text-slate-400 sm:text-xl ${centered ? "mx-auto max-w-2xl" : "max-w-xl"}`}>
130	                {sub}
131	              </p>
132	            )}
133	            {(primary || secondary) && (
134	              <div className={`mt-9 flex flex-wrap gap-3 ${centered ? "justify-center" : ""}`}>
135	                {primary && (
136	                  <Link href={primary.href} className="btn-primary px-5 py-3 text-base">
137	                    {primary.label}
138	                  </Link>
139	                )}
140	                {secondary && (
141	                  <Link href={secondary.href} className="btn-secondary px-5 py-3 text-base">
142	                    {secondary.label}
143	                  </Link>
144	                )}
145	              </div>
146	            )}
147	            {children}
148	          </Reveal>
149	          {visual && <Reveal className="lg:pl-6">{visual}</Reveal>}
150	        </div>
151	      </div>
152	    </section>
153	  );
154	}
