"use client";

import { useEffect, useState } from "react";

/**
 * Sticky product switcher for the /pricing multi-product hub. Pure navigation:
 * anchor links to the five DB-fed product sections (VPS · Game Servers · Shared
 * Hosting · Business Email · Domains) with an active-section highlight driven by
 * a scroll spy. It renders NO prices — every price on the page is server-rendered
 * from the database in the section it belongs to, so this component never risks
 * drifting from the catalogue.
 */
export type NavItem = { id: string; label: string; accent: "violet" | "emerald" | "cyan" | "sky" | "amber" };

const ACCENT: Record<NavItem["accent"], { on: string; dot: string }> = {
  violet: { on: "from-accent-blue to-brand-500", dot: "bg-brand-400" },
  emerald: { on: "from-emerald-500 to-teal-500", dot: "bg-emerald-400" },
  cyan: { on: "from-accent-cyan to-accent-blue", dot: "bg-accent-cyan" },
  sky: { on: "from-sky-500 to-accent-blue", dot: "bg-sky-400" },
  amber: { on: "from-amber-500 to-orange-500", dot: "bg-amber-400" },
};

export function PricingNav({ items }: { items: NavItem[] }) {
  const [active, setActive] = useState(items[0]?.id ?? "");

  useEffect(() => {
    const sections = items
      .map((i) => document.getElementById(i.id))
      .filter((el): el is HTMLElement => !!el);
    if (sections.length === 0) return;

    const observer = new IntersectionObserver(
      (entries) => {
        // Pick the entry nearest the top of the viewport that is intersecting.
        const visible = entries
          .filter((e) => e.isIntersecting)
          .sort((a, b) => a.boundingClientRect.top - b.boundingClientRect.top);
        if (visible[0]) setActive(visible[0].target.id);
      },
      // Bias the "active" band to just under the sticky header + nav.
      { rootMargin: "-150px 0px -55% 0px", threshold: 0 },
    );
    sections.forEach((s) => observer.observe(s));
    return () => observer.disconnect();
  }, [items]);

  return (
    <div className="sticky top-[72px] z-40 -mx-5 border-b border-white/[0.06] bg-navy-950/85 px-5 backdrop-blur-xl">
      <nav className="rail flex gap-2 overflow-x-auto py-3 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
        {items.map((it) => {
          const on = active === it.id;
          const a = ACCENT[it.accent];
          return (
            <a
              key={it.id}
              href={`#${it.id}`}
              onClick={() => setActive(it.id)}
              className={`flex shrink-0 items-center gap-2 rounded-xl border px-4 py-2 text-sm font-semibold transition-all ${
                on
                  ? `border-transparent bg-gradient-to-r ${a.on} text-white shadow-lg`
                  : "border-white/10 bg-white/[0.03] text-slate-400 hover:border-white/25 hover:text-white"
              }`}
            >
              <span className={`h-1.5 w-1.5 rounded-full ${on ? "bg-white" : a.dot}`} />
              {it.label}
            </a>
          );
        })}
      </nav>
    </div>
  );
}

import Link from "next/link";
import type { Metadata } from "next";
import { db } from "@/lib/db";
import { GAME_FAMILIES } from "@/lib/games";
import { currentPromo } from "@/lib/promotions";
import { firstMonthFreeAppliesTo } from "@/lib/promo-redemption";
import { Reveal } from "@/components/marketing/Reveal";
import { PricingNav, type NavItem } from "@/components/marketing/PricingNav";
import { POPULAR_TLDS } from "@/components/marketing/tlds";
import { Section, SectionTitle, PageHero } from "@/components/marketing/primitives";
import { CtaBand } from "@/components/marketing/sections";
import { ProductJsonLd, FaqJsonLd } from "@/components/marketing/StructuredData";
import {
  IconCheck,
  IconGlobe,
  IconShield,
  IconBackup,
  IconTerminal,
  IconNvme,
  IconServer,
  IconGame,
  IconApps,
  IconMail,
  IconArrow,
} from "@/components/marketing/icons";

export const dynamic = "force-dynamic";

export const metadata: Metadata = {
  title: "Pricing",
  description:
    "One place to compare every Nxeon product — Cloud VPS, game servers, shared web hosting, business email and domains. Live catalogue prices, monthly billing, no lock-in.",
  alternates: { canonical: "/pricing" },
};

/**
 * The ONE money helper for this page. Every price rendered below is passed
 * through here straight from a database record (db.plan / db.hostingPlan /
 * db.emailPlan / db.gamePlan) — there is not a single hard-coded plan price on
 * this page, so a catalogue edit propagates here automatically and can never
 * advertise a number checkout won't honour. (Domain TLDs are the one exception
 * and are explicitly labelled "indicative" — there is no TLD price table to read
 * and the domain search quotes the live, exact figure.)
 */
function money(cents: number): string {
  const v = cents / 100;
  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
}
function gb(mb: number): string {
  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
}

const NAV: NavItem[] = [
  { id: "vps", label: "Cloud VPS", accent: "violet" },
  { id: "game-servers", label: "Game Servers", accent: "emerald" },
  { id: "hosting", label: "Shared Hosting", accent: "cyan" },
  { id: "email", label: "Business Email", accent: "sky" },
  { id: "domains", label: "Domains", accent: "amber" },
];

// Router: "which product is right for me?" — sends a buyer to the right section
// before they hit raw numbers (Hostinger/IONOS-style chooser).
const CHOOSER = [
  { icon: <IconTerminal />, who: "I'm a developer", need: "Full root, any stack, resize on demand", to: "#vps", cta: "Cloud VPS" },
  { icon: <IconGame />, who: "I host for my crew", need: "Low-latency game servers, one-click deploy", to: "#game-servers", cta: "Game Servers" },
  { icon: <IconApps />, who: "I want a website online", need: "WordPress, SSL & a control panel — no server to manage", to: "#hosting", cta: "Shared Hosting" },
  { icon: <IconMail />, who: "I just need email", need: "Mailboxes at your own domain, dedicated storage", to: "#email", cta: "Business Email" },
  { icon: <IconGlobe />, who: "I need a domain", need: "Register, manage DNS, point at your VPS", to: "#domains", cta: "Domains" },
];

// Shared "included on every paid plan" trust row — one place, all products.
const INCLUDED = [
  { icon: <IconGlobe />, label: "Free SSL / IPv4" },
  { icon: <IconShield />, label: "DDoS protection" },
  { icon: <IconBackup />, label: "Automatic backups" },
  { icon: <IconServer />, label: "Free migration" },
  { icon: <IconNvme />, label: "NVMe storage" },
];

const VPS_FEATURES = ["Full root access", "Dedicated IPv4", "NVMe SSD storage", "DDoS protection", "Automatic backups", "One-click reinstall"];
const HOSTING_FEATURES = ["Free SSL certificate", "One-click WordPress", "Free site migration", "DDoS protection"];
const EMAIL_FEATURES = ["Webmail + IMAP/SMTP", "Spam & virus filtering", "Shared calendars & contacts", "Automatic MX/SPF setup"];

const FAQ = [
  { q: "How does billing work across products?", a: "Every Nxeon product — VPS, game servers, shared hosting, business email and domains — is billed monthly, prepaid from your wallet balance. Top up, and services auto-renew each month. There is no annual or multi-year lock-in; cancel anytime and billing stops at the end of the period." },
  { q: "Is the first month really free?", a: "On shared web hosting, yes — your first month is on us, then the plan renews at exactly the regular monthly price you see (no teaser jump). The free-month offer applies to shared hosting only; VPS, game servers, business email and domains bill their regular price from month one." },
  { q: "Which product should I choose?", a: "Use the chooser at the top: developers who want full control pick a Cloud VPS; communities hosting games pick a game server; anyone who just wants a website online (WordPress, SSL, a control panel) picks shared hosting; teams who only need professional mailboxes pick Business Email; and everyone can register a domain to tie it together." },
  { q: "Can I upgrade or downgrade later?", a: "Yes. VPS and game plans resize from the dashboard, hosting and email plans move up or down a tier, and everything stays on the same wallet — no rebuild, no new account." },
  { q: "Are the prices shown what I actually pay?", a: "Yes. Every price on this page is read live from the same catalogue the checkout charges from, so the number you see is the number you pay. Domain extensions show an indicative starting price — search a name for the exact live figure." },
  { q: "What's included on every plan?", a: "Free SSL and a dedicated IP where applicable, always-on DDoS protection, automatic backups, free migration help, and enterprise NVMe storage — the platform is the same whether you're on the smallest or the largest plan." },
];

export default async function PricingPage() {
  // Every product line's prices — read live from the catalogue. Nothing below is
  // hard-coded; if a plan is edited or deactivated in the DB, this page follows.
  const [vpsPlans, hostingPlans, emailPlans, gamePlans] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    db.hostingPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }).catch(() => []),
    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }).catch(() => []),
    db.gamePlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }).catch(() => []),
  ]);

  // Group game plans by family, in canonical order, keeping only families that
  // actually have a real per-game plan (honesty: no per-game price is claimed
  // over a title that lacks one — those deploy on a plain VPS instead).
  const byGame = new Map<string, typeof gamePlans>();
  for (const g of gamePlans) {
    if (!byGame.has(g.gameFamily)) byGame.set(g.gameFamily, []);
    byGame.get(g.gameFamily)!.push(g);
  }
  const games = GAME_FAMILIES.filter((f) => (byGame.get(f)?.length ?? 0) > 0);
  const GAME_META: Record<string, { name: string; tag: string }> = {
    minecraft: { name: "Minecraft", tag: "Java & Bedrock" },
    valheim: { name: "Valheim", tag: "Dedicated world" },
    rust: { name: "Rust", tag: "High player counts" },
    palworld: { name: "Palworld", tag: "Co-op survival" },
    cs2: { name: "Counter-Strike 2", tag: "Competitive FPS" },
    terraria: { name: "Terraria", tag: "Sandbox worlds" },
  };

  // Promo copy comes from the single source of truth. It is shown ONLY where the
  // owner scoped it — shared web hosting — via firstMonthFreeAppliesTo("HOSTING").
  const promo = currentPromo(new Date());
  const hostingHasPromo = firstMonthFreeAppliesTo("HOSTING");

  const vpsFrom = vpsPlans.length ? Math.min(...vpsPlans.map((p) => p.priceCents)) : null;

  return (
    <>
      {vpsPlans.length > 0 && <ProductJsonLd plans={vpsPlans} />}
      <FaqJsonLd items={FAQ} />

      <PageHero
        eyebrow="Pricing"
        title="One account. Everything you"
        highlight="build online."
        sub="Compare every Nxeon product in one place — Cloud VPS, game servers, shared web hosting, business email and domains. Live catalogue prices, billed monthly from your wallet, no lock-in."
        primary={{ label: "Create your account", href: "/register" }}
        secondary={{ label: "Find my product", href: "#chooser" }}
      />

      {/* Which product is right for me? */}
      <Section size="md" id="chooser">
        <SectionTitle
          eyebrow="Not sure where to start?"
          title="Which product is right for me?"
          sub="Tell us what you're doing and we'll point you at the right line — then compare the real prices below."
        />
        <Reveal className="mt-10">
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
            {CHOOSER.map((c) => (
              <a
                key={c.to}
                href={c.to}
                className="card card-hover group flex items-start gap-4"
              >
                <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 text-brand-300">
                  {c.icon}
                </span>
                <div className="min-w-0">
                  <h3 className="text-base font-semibold text-white">{c.who}</h3>
                  <p className="mt-1 text-sm leading-relaxed text-slate-400">{c.need}</p>
                  <span className="mt-2 inline-flex items-center gap-1 text-sm font-semibold text-brand-300">
                    {c.cta} <IconArrow size={14} />
                  </span>
                </div>
              </a>
            ))}
          </div>
        </Reveal>
      </Section>

      {/* Sticky product switcher */}
      <PricingNav items={NAV} />

      {/* ===================== VPS ===================== */}
      <Section size="lg" id="vps" className="scroll-mt-[150px]">
        <SectionTitle
          align="left"
          eyebrow="Cloud VPS"
          title="Full-control virtual servers"
          sub="Root access, a dedicated IPv4, NVMe storage and DDoS protection on every plan — you only choose how much horsepower you need. Billed monthly, resize anytime."
        />
        {vpsPlans.length === 0 ? (
          <p className="mt-10 text-slate-400">Plans are being provisioned — check back shortly.</p>
        ) : (
          <Reveal className="mt-10">
            <div className="card overflow-x-auto p-0">
              <table className="table-shell min-w-[680px]">
                <thead>
                  <tr>
                    <th>Plan</th>
                    {vpsPlans.map((p) => (
                      <th key={p.id} className="text-center">
                        {p.name}
                        <div className="mt-1 text-sm font-bold text-white">{money(p.priceCents)}/mo</div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td className="font-medium text-slate-300">vCPU</td>
                    {vpsPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.cpuCores}</td>)}
                  </tr>
                  <tr>
                    <td className="font-medium text-slate-300">RAM</td>
                    {vpsPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{gb(p.ramMB)}</td>)}
                  </tr>
                  <tr>
                    <td className="font-medium text-slate-300">Storage</td>
                    {vpsPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.diskGB} GB</td>)}
                  </tr>
                  <tr>
                    <td className="font-medium text-slate-300">Bandwidth</td>
                    {vpsPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.bandwidthTB} TB</td>)}
                  </tr>
                  {VPS_FEATURES.map((feat) => (
                    <tr key={feat}>
                      <td className="font-medium text-slate-300">{feat}</td>
                      {vpsPlans.map((p) => (
                        <td key={p.id} className="text-center">
                          <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400"><IconCheck size={13} /></span>
                        </td>
                      ))}
                    </tr>
                  ))}
                  <tr>
                    <td />
                    {vpsPlans.map((p) => (
                      <td key={p.id} className="text-center">
                        <Link href="/register" className="btn-secondary inline-flex px-4 py-2 text-xs">Deploy</Link>
                      </td>
                    ))}
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="mt-4 text-sm text-slate-500">
              {vpsFrom != null ? `From ${money(vpsFrom)}/mo. ` : ""}Billed monthly from your wallet — the price shown is the price you pay, at sign-up and at renewal.{" "}
              <Link href="/vps" className="text-brand-300 hover:underline">Explore VPS</Link>
            </p>
          </Reveal>
        )}
      </Section>

      {/* ===================== GAME SERVERS ===================== */}
      <Section tone="panel" size="lg" id="game-servers" className="scroll-mt-[150px]">
        <SectionTitle
          align="left"
          eyebrow="Game Servers"
          title="Per-game plans, honestly priced"
          sub="Six popular titles get dedicated per-game plans tuned to how they run — anything else deploys on a Nxeon VPS. Prices are per game, per month, all-in."
        />
        {games.length === 0 ? (
          <p className="mt-10 text-slate-400">Game plans are being configured — check back shortly.</p>
        ) : (
          <div className="mt-10 space-y-12">
            {games.map((fam) => {
              const meta = GAME_META[fam] ?? { name: fam, tag: "" };
              const tiers = (byGame.get(fam) ?? []).slice().sort((a, b) => a.priceCents - b.priceCents);
              const from = Math.min(...tiers.map((t) => t.priceCents));
              return (
                <Reveal key={fam}>
                  <div className="flex flex-wrap items-baseline justify-between gap-2">
                    <div>
                      <h3 className="text-xl font-bold text-white">{meta.name}</h3>
                      {meta.tag && <p className="text-sm text-slate-400">{meta.tag}</p>}
                    </div>
                    <span className="text-sm text-slate-400">from <span className="font-semibold text-emerald-300">{money(from)}/mo</span></span>
                  </div>
                  <div className="mt-4 grid gap-4 sm:grid-cols-2 lg:grid-cols-3">
                    {tiers.map((t) => (
                      <div key={t.id} className={`card flex h-full flex-col ${t.featured ? "border-emerald-400/50 ring-1 ring-emerald-400/30" : ""}`}>
                        <div className="flex items-center justify-between gap-2">
                          <span className="font-semibold text-white">{t.name}</span>
                          {t.featured && <span className="rounded-full border border-emerald-500/40 bg-emerald-500/10 px-2 py-0.5 text-[11px] text-emerald-300">Popular</span>}
                        </div>
                        <p className="mt-3 text-3xl font-extrabold tracking-tight text-white">
                          {money(t.priceCents)}
                          <span className="text-sm font-normal text-slate-400">{t.termMonths > 1 ? ` / ${t.termMonths} mo` : " /mo"}</span>
                        </p>
                        <ul className="mt-4 space-y-2 text-sm text-slate-300">
                          <li className="flex items-center gap-2"><IconCheck size={14} /> {gb(t.ramMB)} RAM</li>
                          <li className="flex items-center gap-2"><IconCheck size={14} /> {t.cpuCores} vCPU · {t.diskGB} GB NVMe</li>
                          {t.slots != null && <li className="flex items-center gap-2"><IconCheck size={14} /> Up to {t.slots} player slots</li>}
                          <li className="flex items-center gap-2"><IconCheck size={14} /> DDoS protection & full control</li>
                        </ul>
                        <Link href="/register" className="btn-primary mt-5 w-full text-center">Deploy</Link>
                      </div>
                    ))}
                  </div>
                </Reveal>
              );
            })}
          </div>
        )}
        <Reveal className="mt-10">
          <div className="card flex flex-col items-start gap-4 sm:flex-row sm:items-center sm:justify-between">
            <div>
              <h3 className="text-base font-semibold text-white">Playing something else?</h3>
              <p className="mt-1 max-w-xl text-sm leading-relaxed text-slate-400">
                Titles without a dedicated plan — ARK, Satisfactory, FiveM, Garry&apos;s Mod and more — run as a
                custom install on a standard Nxeon VPS. Same control, priced at the regular VPS tiers above.
              </p>
            </div>
            <Link href="/game-servers" className="btn-secondary shrink-0">All game servers <IconArrow size={15} /></Link>
          </div>
        </Reveal>
      </Section>

      {/* ===================== SHARED HOSTING ===================== */}
      <Section size="lg" id="hosting" className="scroll-mt-[150px]">
        <SectionTitle
          align="left"
          eyebrow="Shared Hosting"
          title="Websites, without the server"
          sub="One-click WordPress, free SSL, a friendly control panel and free migration — we manage the box, you run the site. Billed monthly, no lock-in."
        />
        {hostingHasPromo && (
          <Reveal className="mt-6">
            <span className="inline-flex items-center gap-2 rounded-full border border-emerald-500/25 bg-emerald-500/10 px-4 py-1.5 text-sm font-medium text-emerald-300">
              <span className="flex h-1.5 w-1.5 rounded-full bg-emerald-400 animate-pulse-dot" />
              {promo.label} on shared hosting — then the price you sign up at is the price you renew at
            </span>
          </Reveal>
        )}
        {hostingPlans.length === 0 ? (
          <p className="mt-10 text-slate-400">Hosting plans are being provisioned — check back shortly.</p>
        ) : (
          <Reveal className="mt-8">
            <div className="card overflow-x-auto p-0">
              <table className="table-shell min-w-[620px]">
                <thead>
                  <tr>
                    <th>Plan</th>
                    {hostingPlans.map((p) => (
                      <th key={p.id} className="text-center">
                        {p.name}
                        <div className="mt-1 text-sm font-bold text-white">{money(p.priceCents)}/mo</div>
                        {hostingHasPromo && <div className="text-[11px] font-medium text-emerald-300">{promo.label} · then {money(p.priceCents)}/mo</div>}
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td className="font-medium text-slate-300">Disk</td>
                    {hostingPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.diskGB} GB</td>)}
                  </tr>
                  <tr>
                    <td className="font-medium text-slate-300">Websites</td>
                    {hostingPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.maxSites}</td>)}
                  </tr>
                  <tr>
                    <td className="font-medium text-slate-300">Databases</td>
                    {hostingPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.maxDatabases}</td>)}
                  </tr>
                  <tr>
                    <td className="font-medium text-slate-300">Bandwidth</td>
                    {hostingPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.bandwidthTB} TB</td>)}
                  </tr>
                  <tr>
                    <td className="font-medium text-slate-300">Included mailboxes</td>
                    {hostingPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.mailboxes < 0 ? "Unlimited" : p.mailboxes}</td>)}
                  </tr>
                  {HOSTING_FEATURES.map((feat) => (
                    <tr key={feat}>
                      <td className="font-medium text-slate-300">{feat}</td>
                      {hostingPlans.map((p) => (
                        <td key={p.id} className="text-center">
                          <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400"><IconCheck size={13} /></span>
                        </td>
                      ))}
                    </tr>
                  ))}
                  <tr>
                    <td />
                    {hostingPlans.map((p) => (
                      <td key={p.id} className="text-center">
                        <Link href="/register" className="btn-secondary inline-flex px-4 py-2 text-xs">Start free</Link>
                      </td>
                    ))}
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="mt-4 text-sm text-slate-500">
              {hostingHasPromo ? "First month free, then renews at the regular monthly price shown. " : ""}
              Need more mailboxes without a website? See{" "}
              <Link href="#email" className="text-brand-300 hover:underline">Business Email</Link>.{" "}
              <Link href="/web-hosting" className="text-brand-300 hover:underline">Explore Web Hosting</Link>
            </p>
          </Reveal>
        )}
      </Section>

      {/* ===================== BUSINESS EMAIL ===================== */}
      <Section tone="panel" size="lg" id="email" className="scroll-mt-[150px]">
        <SectionTitle
          align="left"
          eyebrow="Business Email"
          title="Professional mailboxes at your domain"
          sub="you@yourdomain mailboxes with dedicated per-mailbox storage, shared calendars and contacts, and spam filtering — with no website disk to share. Billed monthly."
        />
        {emailPlans.length === 0 ? (
          <p className="mt-10 text-slate-400">Email plans are being finalised — check back shortly.</p>
        ) : (
          <Reveal className="mt-10">
            <div className="card overflow-x-auto p-0">
              <table className="table-shell min-w-[560px]">
                <thead>
                  <tr>
                    <th>Plan</th>
                    {emailPlans.map((p) => (
                      <th key={p.id} className="text-center">
                        {p.name}
                        <div className="mt-1 text-sm font-bold text-white">{money(p.priceCents)}{p.termMonths > 1 ? ` / ${p.termMonths} mo` : "/mo"}</div>
                      </th>
                    ))}
                  </tr>
                </thead>
                <tbody>
                  <tr>
                    <td className="font-medium text-slate-300">Mailboxes</td>
                    {emailPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.mailboxes}</td>)}
                  </tr>
                  <tr>
                    <td className="font-medium text-slate-300">Storage / mailbox</td>
                    {emailPlans.map((p) => <td key={p.id} className="text-center text-slate-300">{p.storageGB} GB</td>)}
                  </tr>
                  {EMAIL_FEATURES.map((feat) => (
                    <tr key={feat}>
                      <td className="font-medium text-slate-300">{feat}</td>
                      {emailPlans.map((p) => (
                        <td key={p.id} className="text-center">
                          <span className="inline-flex h-5 w-5 items-center justify-center rounded-full bg-emerald-500/15 text-emerald-400"><IconCheck size={13} /></span>
                        </td>
                      ))}
                    </tr>
                  ))}
                  <tr>
                    <td />
                    {emailPlans.map((p) => (
                      <td key={p.id} className="text-center">
                        <Link href="/register" className="btn-secondary inline-flex px-4 py-2 text-xs">Get started</Link>
                      </td>
                    ))}
                  </tr>
                </tbody>
              </table>
            </div>
            <p className="mt-4 text-sm text-slate-500">
              Storage is dedicated per mailbox — it isn&apos;t shared with a website like a hosting plan&apos;s bundled email.{" "}
              <Link href="/business-email" className="text-brand-300 hover:underline">Explore Business Email</Link>
            </p>
          </Reveal>
        )}
      </Section>

      {/* ===================== DOMAINS ===================== */}
      <Section size="lg" id="domains" className="scroll-mt-[150px]">
        <SectionTitle
          align="left"
          eyebrow="Domains"
          title="Register the name, own the DNS"
          sub="Free WhoisGuard privacy, full DNS management and one-click pointing at your Nxeon VPS. Renewed monthly-billing-friendly from the same wallet as everything else."
        />
        <Reveal className="mt-10">
          <div className="grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4">
            {POPULAR_TLDS.map((t) => (
              <div key={t.tld} className="group flex items-center justify-between rounded-2xl border border-white/[0.06] bg-navy-900/60 px-5 py-4 backdrop-blur-md transition-all duration-200 hover:-translate-y-0.5 hover:border-brand-500/30 hover:bg-navy-850/70">
                <span className="font-mono text-lg font-bold text-white">{t.tld}</span>
                <span className="text-right text-sm">
                  <span className="text-slate-500">from </span>
                  <span className="font-semibold text-brand-300">{money(t.fromCents)}/yr</span>
                </span>
              </div>
            ))}
          </div>
        </Reveal>
        <p className="mt-6 text-sm text-slate-500">
          Indicative starting prices per year — premium names are priced individually. Search a name for the live, exact figure.{" "}
          <Link href="/domains" className="text-brand-300 hover:underline">Search a domain</Link>
        </p>
      </Section>

      {/* Shared "included on every plan" trust row */}
      <Section tone="panel" size="md">
        <SectionTitle
          eyebrow="On every paid plan"
          title="The good stuff isn't an upsell"
          sub="Across every product, the same platform guarantees ship as standard — you only ever pay for capacity, never for the essentials."
        />
        <Reveal className="mt-10">
          <div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-5">
            {INCLUDED.map((f) => (
              <div key={f.label} className="card flex flex-col items-center gap-3 text-center">
                <span className="flex h-11 w-11 items-center justify-center rounded-xl border border-white/[0.08] bg-gradient-to-br from-accent-blue/20 to-brand-500/20 text-brand-300">
                  {f.icon}
                </span>
                <span className="text-sm font-semibold text-white">{f.label}</span>
              </div>
            ))}
          </div>
        </Reveal>
      </Section>

      {/* FAQ */}
      <Section size="md">
        <SectionTitle eyebrow="FAQ" title="Questions, answered" />
        <div className="mx-auto mt-10 max-w-3xl space-y-4">
          {FAQ.map((f, i) => (
            <Reveal key={f.q} delay={i * 40}>
              <div className="card">
                <h3 className="text-base font-semibold text-white">{f.q}</h3>
                <p className="mt-2 text-sm leading-relaxed text-slate-400">{f.a}</p>
              </div>
            </Reveal>
          ))}
        </div>
        <p className="mt-8 text-center text-sm text-slate-500">
          Still have questions?{" "}
          <Link href="/contact" className="text-brand-300 hover:underline">Get in touch</Link>.
        </p>
      </Section>

      <Section tone="deep" size="lg">
        <CtaBand />
      </Section>
    </>
  );
}

